return (async () => {
  const result = [];
  for (const page of figma.root.children) {
    const pageData = { name: page.name, id: page.id, components: [] };
    const components = page.findAll(n => n.type === 'COMPONENT' || n.type === 'COMPONENT_SET');
    for (const c of components) {
      pageData.components.push({ type: c.type, name: c.name, id: c.id });
    }
    result.push(pageData);
  }
  return result;
})();

return (async () => {
  const getSubtree = (node) => {
    const data = {
      id: node.id,
      name: node.name,
      type: node.type,
      x: node.x,
      y: node.y,
      width: node.width,
      height: node.height,
    };
    if (node.fills) data.fills = JSON.parse(JSON.stringify(node.fills));
    if (node.strokes) data.strokes = JSON.parse(JSON.stringify(node.strokes));
    if (node.effects) data.effects = JSON.parse(JSON.stringify(node.effects));
    if (node.type === 'TEXT') {
      data.characters = node.characters;
      data.fontSize = node.fontSize;
      data.fontName = node.fontName;
    }
    if (node.children) {
      data.children = node.children.map(getSubtree);
    }
    return data;
  };

  const compPage = figma.root.children.find(p => p.id === '1:3');
  const details = [];
  const comps = compPage.findAll(n => n.type === 'COMPONENT');
  for (const c of comps) {
    details.push(getSubtree(c));
  }
  return details;
})();

return (async () => {
  const result = {};
  const coinPage = figma.root.children.find(p => p.id === '1:4');
  const components = coinPage.findAll(n => n.type === 'COMPONENT');
  for (const c of components) {
    result[c.name] = { id: c.id, width: c.width, height: c.height };
  }
  return result;
})();

return (async () => {
  const page = figma.root.children.find(p => p.id === '4:2');
  if (!page) {
    return "Page '03 · Workspace' (4:2) not found";
  }
  await figma.setCurrentPageAsync(page);

  // Try loading fonts
  const fonts = [
    { family: "Nunito", style: "Regular" },
    { family: "Nunito", style: "Medium" },
    { family: "Nunito", style: "SemiBold" },
    { family: "Nunito", style: "Bold" },
    { family: "Nunito", style: "ExtraBold" },
    { family: "Inter", style: "Semi Bold" },
    { family: "Inter", style: "Regular" }
  ];

  const results = [];
  for (const f of fonts) {
    try {
      await figma.loadFontAsync(f);
      results.push(`${f.family} ${f.style}: SUCCESS`);
    } catch (err) {
      results.push(`${f.family} ${f.style}: FAILED (${err.message})`);
    }
  }
  return {
    currentPage: figma.currentPage.name,
    fonts: results
  };
})();

