return (async () => {
  const result = {};
  const mediaPage = figma.root.children.find(p => p.id === '1:4');
  const components = mediaPage.findAll(n => n.type === 'COMPONENT');
  for (const c of components) {
    if (c.name.startsWith('Icon_')) {
      // Find the vector or paths inside
      const vectors = c.findAll(n => n.type === 'VECTOR' || n.type === 'BOOLEAN_OPERATION');
      result[c.name] = vectors.map(v => ({ id: v.id, name: v.name, fills: v.fills, strokes: v.strokes }));
    }
  }
  return result;
})();

