return (async () => {
  // Let's create beautiful interactive prototype flows as specified in the brief:
  // 1. Swipe or Page navigation:
  //    - 01_Wallet -> swipe/page indicator -> 02_Discovery
  //    - 02_Discovery -> swipe/page indicator -> 01_Wallet
  //    Wait, we can link the My Wallet tab in 02_Discovery navbar to 01_Wallet, and the Discovery tab in 01_Wallet navbar to 02_Discovery!
  //    Yes! Let's wire those tab button zones up.
  // 2. Invest flow:
  //    - 02_Discovery -> Aggressive Growth card -> 03_Strategy
  //    - 03_Strategy -> Invest Button -> 04_Invest_Amount
  //    - 03_Strategy -> Dismiss Close Icon -> 02_Discovery
  //    - 04_Invest_Amount -> Back arrow -> 03_Strategy
  //    - 04_Invest_Amount -> Hold to Invest Button -> 05_Invest_Success
  //    - 05_Invest_Success -> Close Icon -> 02_Discovery
  //    - 05_Invest_Success -> View Pocket Button -> 01_Wallet

  const f1 = figma.currentPage.findOne(n => n.name === "01_Wallet" && n.type === "FRAME");
  const f2 = figma.currentPage.findOne(n => n.name === "02_Discovery" && n.type === "FRAME");
  const f3 = figma.currentPage.findOne(n => n.name === "03_Strategy" && n.type === "FRAME");
  const f4 = figma.currentPage.findOne(n => n.name === "04_Invest_Amount" && n.type === "FRAME");
  const f5 = figma.currentPage.findOne(n => n.name === "05_Invest_Success" && n.type === "FRAME");

  if (!f1 || !f2 || !f3 || !f4 || !f5) {
    return "Error: Could not locate all 5 frames for prototyping.";
  }

  // Helper to add tap navigation action
  const setTapNav = (sourceNode, targetNode, animType = "SLIDE_IN") => {
    sourceNode.reactions = [{
      trigger: { type: "ON_CLICK" },
      actions: [{
        type: "NODE",
        destinationId: targetNode.id,
        navigation: "NAVIGATE",
        transition: animType === "SLIDE_IN" ? {
          type: "SLIDE_IN",
          direction: "RIGHT",
          duration: 0.3,
          easing: { type: "EASE_IN_OUT" }
        } : {
          type: "DISSOLVE",
          duration: 0.2,
          easing: { type: "EASE_IN_OUT" }
        }
      }]
    }];
  };

  // 1. Navigation Links:
  // 01_Wallet "Discovery" Tab (in Nav_Bar) -> 02_Discovery
  const tabDiscoveryInWallet = f1.findOne(n => n.name === "Nav_Bar").findOne(n => n.characters === "Discovery");
  if (tabDiscoveryInWallet) {
    setTapNav(tabDiscoveryInWallet, f2, "DISSOLVE");
  }

  // 02_Discovery "My Wallet" Tab (in Nav_Bar) -> 01_Wallet
  const tabWalletInDisc = f2.findOne(n => n.name === "Nav_Bar").findOne(n => n.characters === "My Wallet");
  if (tabWalletInDisc) {
    setTapNav(tabWalletInDisc, f1, "DISSOLVE");
  }

  // 2. Invest Flow:
  // 02_Discovery -> "Aggressive Growth" Strategy Card -> 03_Strategy
  // Let's find the card inside Inner_Layout -> Strategy_Card_Aggressive_Growth
  const aggCard = f2.findOne(n => n.name === "Strategy_Card_Aggressive_Growth");
  if (aggCard) {
    setTapNav(aggCard, f3, "SLIDE_IN");
  }

  // 03_Strategy "Invest" Button -> 04_Invest_Amount
  const investBtn = f3.findOne(n => n.name === "Bottom_Sheet").findOne(n => n.name === "Invest_Bar").findOne(n => n.name === "Button");
  if (investBtn) {
    setTapNav(investBtn, f4, "SLIDE_IN");
  }

  // 03_Strategy Close Icon -> 02_Discovery
  const closeBtn3 = f3.findOne(n => n.name === "Bottom_Sheet").findOne(n => n.name === "Status Bar" || n.name === "Icon_Close" || n.type === "INSTANCE" && n.name === "Icon_Close");
  if (closeBtn3) {
    setTapNav(closeBtn3, f2, "DISSOLVE");
  }

  // 04_Invest_Amount Back button -> 03_Strategy
  const backBtn4 = f4.findOne(n => n.name === "Bottom_Sheet").findOne(n => n.name === "Icon_Back");
  if (backBtn4) {
    setTapNav(backBtn4, f3, "DISSOLVE");
  }

  // 04_Invest_Amount "Hold to Invest" button -> 05_Invest_Success
  const holdBtn4 = f4.findOne(n => n.name === "Bottom_Sheet").findOne(n => n.name === "Action_Panel").findOne(n => n.name === "Hold_To_Invest_Button");
  if (holdBtn4) {
    setTapNav(holdBtn4, f5, "SLIDE_IN");
  }

  // 05_Invest_Success Close button -> 02_Discovery
  const closeBtn5 = f5.findOne(n => n.name === "Bottom_Sheet").findOne(n => n.name === "Icon_Close");
  if (closeBtn5) {
    setTapNav(closeBtn5, f2, "DISSOLVE");
  }

  // 05_Invest_Success "View Pocket" button -> 01_Wallet
  const viewBtn5 = f5.findOne(n => n.name === "Bottom_Sheet").findOne(n => n.name === "Action_Panel").findOne(n => n.name === "View_Pocket_Button");
  if (viewBtn5) {
    setTapNav(viewBtn5, f1, "SLIDE_IN");
  }

  return "Prototype interaction connections completed successfully!";
})();

return (async () => {
  const f1 = figma.currentPage.findOne(n => n.name === "01_Wallet" && n.type === "FRAME");
  const f2 = figma.currentPage.findOne(n => n.name === "02_Discovery" && n.type === "FRAME");
  const f3 = figma.currentPage.findOne(n => n.name === "03_Strategy" && n.type === "FRAME");
  const f4 = figma.currentPage.findOne(n => n.name === "04_Invest_Amount" && n.type === "FRAME");
  const f5 = figma.currentPage.findOne(n => n.name === "05_Invest_Success" && n.type === "FRAME");

  const printStructure = (node, depth = 0) => {
    let result = "  ".repeat(depth) + `- ${node.name} (${node.type}, id: ${node.id})\n`;
    if (node.children) {
      for (const child of node.children) {
        result += printStructure(child, depth + 1);
      }
    }
    return result;
  };

  return {
    f1: f1 ? printStructure(f1) : "NOT FOUND",
    f2: f2 ? printStructure(f2) : "NOT FOUND",
    f3: f3 ? printStructure(f3) : "NOT FOUND",
    f4: f4 ? printStructure(f4) : "NOT FOUND",
    f5: f5 ? printStructure(f5) : "NOT FOUND"
  };
})();

