return (async () => {
  const result = [];
  for (const page of figma.root.children) {
    const frames = page.findAll(n => n.type === 'FRAME' && ["01_Wallet", "02_Discovery", "03_Strategy", "04_Invest_Amount", "05_Invest_Success"].includes(n.name));
    for (const f of frames) {
      result.push({ pageName: page.name, pageId: page.id, frameName: f.name, frameId: f.id, parent: f.parent ? f.parent.name : null });
    }
  }
  return result;
})();

